for f in packages/blitz-dom/src/events/pointer.rs packages/escher-driver/src/execute.rs packages/dioxus-native-dom/src/graph.rs; do rust-code-analysis-cli -m -O json -p "$f"; echo; done | python3 -c "
import json, sys
over = []
def walk(n, path):
    if n.get(\"kind\") == \"function\" and n[\"metrics\"][\"cognitive\"][\"sum\"] > 15:
        over.append((path, n[\"name\"], n[\"start_line\"], n[\"metrics\"][\"cognitive\"][\"sum\"]))
    for s in n.get(\"spaces\", []):
        walk(s, path)
for line in sys.stdin:
    line = line.strip()
    if line:
        d = json.loads(line)
        walk(d, d[\"name\"])
for o in over:
    print(*o)
print(len(over))
"

